//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_FeedControl_RetriveData                                                                                                                                                                                                                                                           
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-05-22		William Veim			Initial release
//
//==============================================================================================================================
//
// 		FUNCTIONALITY:
// 		Retrive data for FeedControl - Temperature, SGR factor, FCR factor and current amount per sec for feed screws
//
//==============================================================================================================================

(*************************************************************************
*	RETRIVING CURRENT TEMPERATURE
*************************************************************************)
	
CASE Ext_FeedControl.EXT_Operator.Temperature_Select OF

	0: //Temperature - Manual
	Temperature_Current := Ext_FeedControl.EXT_Operator.Temperature_Manual;

	1: //Selected analog index (Temp A)
	Temperature_Current := Ext_AnalogValue[Ext_FeedControl.EXT_Engineering.Cfg_TempA_Index].EXT_Operator.ProcessValue;
		
	2: //Selected analog index (Temp b)
	Temperature_Current := Ext_AnalogValue[Ext_FeedControl.EXT_Engineering.Cfg_TempB_Index].EXT_Operator.ProcessValue;
	
	3: //Selected analog index (Temp C)
	Temperature_Current := Ext_AnalogValue[Ext_FeedControl.EXT_Engineering.Cfg_TempC_Index].EXT_Operator.ProcessValue;
	
END_CASE;

(*************************************************************************
*	CALCULATING SGR FACTOR
*************************************************************************)

Wrk_LB:=	DINT_TO_INT(LOWER_BOUND(Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow, 1));
Wrk_UB:=	DINT_TO_INT(UPPER_BOUND(Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow, 1));
	
//Retrive current columm index (Based on fish weight)
FOR Wrk_IndexWeightRowSGR:=Wrk_LB TO Wrk_UB DO
	IF (Ext_FeedControl.EXT_Operator.SGR_Factor_Select = 1
	AND Ext_FeedControl.EXT_Operator.Weight_AVG >= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR].Weight_Value
	AND Ext_FeedControl.EXT_Operator.Weight_AVG <= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value)
	OR (Ext_FeedControl.EXT_Operator.SGR_Factor_Select = 2
	AND Ext_FeedControl.EXT_Operator.Weight_AVG >= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR].Weight_Value
	AND Ext_FeedControl.EXT_Operator.Weight_AVG <= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value)
	OR (Ext_FeedControl.EXT_Operator.SGR_Factor_Select = 3
	AND Ext_FeedControl.EXT_Operator.Weight_AVG >= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR].Weight_Value
	AND Ext_FeedControl.EXT_Operator.Weight_AVG <= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value)THEN
		EXIT;
	END_IF;
END_FOR;

CASE Ext_FeedControl.EXT_Operator.SGR_Factor_Select OF 
	
	//MANUAL FACTOR
	//----------------
	0: 
	
	SGR_Factor:= Ext_FeedControl.EXT_Operator.SGR_Factor_Manual;
	
	//FEED TABLE 1
	//----------------
	1: 
	
	IF Ext_FeedControl.EXT_Operator.Temperature_Current > 1
		AND Ext_FeedControl.EXT_Operator.Temperature_Current <= 17 THEN
		
		Wrk_SGRFactor_Scaling[0]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1];
		Wrk_SGRFactor_Scaling[1]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1];
		Wrk_SGRFactor_Scaling[2]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))];
		Wrk_SGRFactor_Scaling[3]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))];
		
		Wrk_SGRFactor_WeightVector:=	ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																					X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR].Weight_Value, 
																					Y0:=0, 
																					X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value, 
																					Y1:=1);
		
		Wrk_SGRFactor_TempVector:=	ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Temperature_Current, 
																					X0:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current)), 
																					Y0:=0, 
																					X1:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))+1, 
																					Y1:=1);
		
		//Values is valid on all four points - 4 point vector scaling
		IF Wrk_SGRFactor_Scaling[0] > 0 
			AND Wrk_SGRFactor_Scaling[1] > 0
			AND Wrk_SGRFactor_Scaling[2] > 0 
			AND Wrk_SGRFactor_Scaling[3] > 0 THEN
			
			SGR_Factor :=	Wrk_SGRFactor_Scaling[0] * (1.0 - Wrk_SGRFactor_WeightVector) * (1.0 - Wrk_SGRFactor_TempVector)
			  																					+ Wrk_SGRFactor_Scaling[1] * Wrk_SGRFactor_WeightVector         * (1.0 - Wrk_SGRFactor_TempVector)
			  																					+ Wrk_SGRFactor_Scaling[2] * (1.0 - Wrk_SGRFactor_WeightVector) * Wrk_SGRFactor_TempVector
			  																					+ Wrk_SGRFactor_Scaling[3] * Wrk_SGRFactor_WeightVector         * Wrk_SGRFactor_TempVector;
																								
		//Only current columm is valid (end of temp range) - 2 point scaling
		ELSIF Wrk_SGRFactor_Scaling[0] > 0 
				AND Wrk_SGRFactor_Scaling[1] > 0 THEN
		
			SGR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																												X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR].Weight_Value, 
																												Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1], 
																												X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value, 
																												Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1]);
																												
		//Only current row is valid (end of weight range) - 2 point scaling
		ELSIF Wrk_SGRFactor_Scaling[2] > 0 
				AND Wrk_SGRFactor_Scaling[3] > 0 THEN
		
			SGR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Temperature_Current, 
																												X0:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current)), 
																												Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1], 
																												X1:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))+1, 
																												Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))]);
		
		//Only current value is valid (end of weight and temp range) - direct value
		ELSIF Wrk_SGRFactor_Scaling[0] > 0 THEN
		
			SGR_Factor:= Wrk_SGRFactor_Scaling[0];
		
		ELSE
			SGR_Factor:=0;
		END_IF;
	ELSE
		SGR_Factor:=0;
	END_IF;
	
	//FEED TABLE 2
	//----------------
	2: 
	
	IF Ext_FeedControl.EXT_Operator.Temperature_Current > 1
		AND Ext_FeedControl.EXT_Operator.Temperature_Current <= 17 THEN

		Wrk_SGRFactor_Scaling[0]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1];
		Wrk_SGRFactor_Scaling[1]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1];
		Wrk_SGRFactor_Scaling[2]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))];
		Wrk_SGRFactor_Scaling[3]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))];
		
		Wrk_SGRFactor_WeightVector:=	ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																					X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR].Weight_Value, 
																					Y0:=0, 
																					X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value, 
																					Y1:=1);
		
		Wrk_SGRFactor_TempVector:=	ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Temperature_Current, 
																					X0:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current)), 
																					Y0:=0, 
																					X1:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))+1, 
																					Y1:=1);
		
		//Values is valid on all four points - 4 point vector scaling
		IF Wrk_SGRFactor_Scaling[0] > 0 
			AND Wrk_SGRFactor_Scaling[1] > 0
			AND Wrk_SGRFactor_Scaling[2] > 0 
			AND Wrk_SGRFactor_Scaling[3] > 0 THEN
			
			SGR_Factor :=	Wrk_SGRFactor_Scaling[0] * (1.0 - Wrk_SGRFactor_WeightVector) * (1.0 - Wrk_SGRFactor_TempVector)
			  																					+ Wrk_SGRFactor_Scaling[1] * Wrk_SGRFactor_WeightVector         * (1.0 - Wrk_SGRFactor_TempVector)
			  																					+ Wrk_SGRFactor_Scaling[2] * (1.0 - Wrk_SGRFactor_WeightVector) * Wrk_SGRFactor_TempVector
			  																					+ Wrk_SGRFactor_Scaling[3] * Wrk_SGRFactor_WeightVector         * Wrk_SGRFactor_TempVector;
																								
		//Only current columm is valid (end of temp range) - 2 point scaling
		ELSIF Wrk_SGRFactor_Scaling[0] > 0 
				AND Wrk_SGRFactor_Scaling[1] > 0 THEN
		
			SGR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																												X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR].Weight_Value, 
																												Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1], 
																												X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value, 
																												Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1]);
																												
		//Only current row is valid (end of weight range) - 2 point scaling
		ELSIF Wrk_SGRFactor_Scaling[2] > 0 
				AND Wrk_SGRFactor_Scaling[3] > 0 THEN
		
			SGR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Temperature_Current, 
																												X0:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current)), 
																												Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1], 
																												X1:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))+1, 
																												Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))]);
		
		//Only current value is valid (end of weight and temp range) - direct value
		ELSIF Wrk_SGRFactor_Scaling[0] > 0 THEN
		
			SGR_Factor:= Wrk_SGRFactor_Scaling[0];
		
		ELSE
			SGR_Factor:=0;
		END_IF;
	ELSE
		SGR_Factor:=0;
	END_IF;
	
	//FEED TABLE 3
	//----------------
	3: 
	
	IF Ext_FeedControl.EXT_Operator.Temperature_Current > 1
		AND Ext_FeedControl.EXT_Operator.Temperature_Current <= 17 THEN
		
		Wrk_SGRFactor_Scaling[0]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1];
		Wrk_SGRFactor_Scaling[1]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1];
		Wrk_SGRFactor_Scaling[2]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))];
		Wrk_SGRFactor_Scaling[3]:= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))];
		
		Wrk_SGRFactor_WeightVector:=	ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																					X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR].Weight_Value, 
																					Y0:=0, 
																					X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value, 
																					Y1:=1);
		
		Wrk_SGRFactor_TempVector:=	ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Temperature_Current, 
																					X0:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current)), 
																					Y0:=0, 
																					X1:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))+1, 
																					Y1:=1);
		
		//Values is valid on all four points - 4 point vector scaling
		IF Wrk_SGRFactor_Scaling[0] > 0 
			AND Wrk_SGRFactor_Scaling[1] > 0
			AND Wrk_SGRFactor_Scaling[2] > 0 
			AND Wrk_SGRFactor_Scaling[3] > 0 THEN
			
			SGR_Factor:= Wrk_SGRFactor_Scaling[0] * (1.0 - Wrk_SGRFactor_WeightVector) * (1.0 - Wrk_SGRFactor_TempVector)
			  																					+ Wrk_SGRFactor_Scaling[1] * Wrk_SGRFactor_WeightVector         * (1.0 - Wrk_SGRFactor_TempVector)
			  																					+ Wrk_SGRFactor_Scaling[2] * (1.0 - Wrk_SGRFactor_WeightVector) * Wrk_SGRFactor_TempVector
			  																					+ Wrk_SGRFactor_Scaling[3] * Wrk_SGRFactor_WeightVector         * Wrk_SGRFactor_TempVector;
																								
		//Only current columm is valid (end of temp range) - 2 point scaling
		ELSIF Wrk_SGRFactor_Scaling[0] > 0 
				AND Wrk_SGRFactor_Scaling[1] > 0 THEN
		
			SGR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																												X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR].Weight_Value, 
																												Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1], 
																												X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR+1].Weight_Value, 
																												Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1]);
																												
		//Only current row is valid (end of weight range) - 2 point scaling
		ELSIF Wrk_SGRFactor_Scaling[2] > 0 
				AND Wrk_SGRFactor_Scaling[3] > 0 THEN
		
			SGR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Temperature_Current, 
																												X0:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current)), 
																												Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))-1], 
																												X1:=DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))+1, 
																												Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowSGR+1].SGR_Value[DINT_TO_UINT(TRUNC(Ext_FeedControl.EXT_Operator.Temperature_Current))]);
		
		//Only current value is valid (end of weight and temp range) - direct value
		ELSIF Wrk_SGRFactor_Scaling[0] > 0 THEN
		
			SGR_Factor:= Wrk_SGRFactor_Scaling[0];
			
		ELSE
			SGR_Factor:=0;
		END_IF;
	ELSE
		SGR_Factor:=0;
	END_IF;
END_CASE;

(*************************************************************************
*	CALCULATING FCR FACTOR
*************************************************************************)

Wrk_LB:=	DINT_TO_INT(LOWER_BOUND(Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow, 1));
Wrk_UB:=	DINT_TO_INT(UPPER_BOUND(Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow, 1));

//Retrive current columm index (Based on fish weight)
FOR Wrk_IndexWeightRowFCR:=Wrk_LB TO Wrk_UB DO
	IF (Ext_FeedControl.EXT_Operator.FCR_Factor_Select = 1
	AND Ext_FeedControl.EXT_Operator.Weight_AVG >= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR].Weight_Value
	AND Ext_FeedControl.EXT_Operator.Weight_AVG <= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR+1].Weight_Value)
	OR (Ext_FeedControl.EXT_Operator.FCR_Factor_Select = 2
	AND Ext_FeedControl.EXT_Operator.Weight_AVG >= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR].Weight_Value
	AND Ext_FeedControl.EXT_Operator.Weight_AVG <= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR+1].Weight_Value)
	OR (Ext_FeedControl.EXT_Operator.FCR_Factor_Select = 3
	AND Ext_FeedControl.EXT_Operator.Weight_AVG >= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR].Weight_Value
	AND Ext_FeedControl.EXT_Operator.Weight_AVG <= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR+1].Weight_Value)THEN
		EXIT;
	END_IF;
END_FOR;

CASE Ext_FeedControl.EXT_Operator.FCR_Factor_Select OF 
	

	
	//MANUAL FACTOR
	//----------------
	0: 
	
	FCR_Factor:= Ext_FeedControl.EXT_Operator.FCR_Factor_Manual;
	
	//FEED TABLE 1
	//----------------
	1: 
	
	IF Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR].FCR_Value > 0
		AND Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR+1].FCR_Value > 0 THEN
		
		FCR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																											X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR].Weight_Value, 
																											Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR].FCR_Value, 
																											X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR+1].Weight_Value, 
																											Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR+1].FCR_Value);
		
	ELSIF Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR].FCR_Value > 0 THEN
		
		FCR_Factor:= Ext_FeedControl_Common.EXT_Operator.Feed_Table1.TableRow[Wrk_IndexWeightRowFCR].FCR_Value;
		
	ELSE
		
		FCR_Factor:=0;
		
	END_IF;
	
	//FEED TABLE 2
	//----------------
	2: 
	
	IF Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR].FCR_Value > 0
		AND Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowSGR+1].FCR_Value > 0 THEN
		
		FCR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																											X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR].Weight_Value, 
																											Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR].FCR_Value, 
																											X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR+1].Weight_Value, 
																											Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR+1].FCR_Value);
		
	ELSIF Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR].FCR_Value > 0 THEN
		
		FCR_Factor:= Ext_FeedControl_Common.EXT_Operator.Feed_Table2.TableRow[Wrk_IndexWeightRowFCR].FCR_Value;
		
	ELSE
		
		FCR_Factor:=0;
		
	END_IF;
	
	//FEED TABLE 3
	//----------------
	3: 
	
	IF Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR].FCR_Value > 0
		AND Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR+1].FCR_Value > 0 THEN
		
		FCR_Factor:= ScaleTrans(SclIn:=Ext_FeedControl.EXT_Operator.Weight_AVG, 
																											X0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR].Weight_Value, 
																											Y0:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR].FCR_Value, 
																											X1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR+1].Weight_Value, 
																											Y1:=Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR+1].FCR_Value);
		
	ELSIF Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR].FCR_Value > 0 THEN
		
		FCR_Factor:= Ext_FeedControl_Common.EXT_Operator.Feed_Table3.TableRow[Wrk_IndexWeightRowFCR].FCR_Value;
		
	ELSE
		
		FCR_Factor:=0;
		
	END_IF;
	
END_CASE;

(*************************************************************************
*	RETRIVING AMOUNT PER SEC FOR EACH FEED SCREW
*************************************************************************)

CASE Ext_FeedControl.EXT_Operator.FeedType_Select OF
	
	0: //Type 1 feed
	
	IF NOT Ext_FeedControl.EXT_General.FeedScrew_Type THEN //Contactor control
		
		FeedScrew1_AmountPerSec := Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.FeedType1_CalibrationValue_LowSpeed;
